// Has reports whether a key is defined for a language, falling back to English
// the same way Get does. Callers use it to decide between a per-feature string
// and a shared one, rather than silently rendering the English copy.
func Has(key, lang string) bool {
	if m, ok := strings[lang]; ok {
		if _, ok := m[key]; ok {
			return true
		}
	}
	_, ok := strings["en"][key]
	return ok
}

func Get(key, lang string, args ...interface{}) string {
	m, ok := strings[lang]
	if !ok {
		m = strings["en"]
	}
	val, ok := m[key]
	if !ok {
		val = strings["en"][key]
	}
	if len(args) > 0 {
		return fmt.Sprintf(val, args...)
	}
	return val
}

func SupportedLanguages() []string {
	var langs []string
	for l := range strings {
		langs = append(langs, l)
	}
	return langs
}

func LanguageName(lang string) string {
	names := map[string]string{
		"en": "English",
		"es": "Español",
		"fr": "Français",
		"de": "Deutsch",
		"hi": "हिन्दी",
		"ur": "اردو",
		"sw": "Kiswahili",
		"ha": "Hausa",
		"yo": "Yorùbá",
		"zu": "isiZulu",
		"am": "አማርኛ",
		"af": "Afrikaans",
		"ig": "Igbo",
	}
	if name, ok := names[lang]; ok {
		return name
	}
	return lang
}
